1	import Link from "next/link";
2	import { IconCheck } from "./icons";
3	import { planTip, planAudience } from "./planTips";
4	
5	export type PlanCard = {
6	  id: string;
7	  name: string;
8	  cpuCores: number;
9	  ramMB: number;
10	  diskGB: number;
11	  bandwidthTB: number;
12	  priceCents: number;
13	  storageTier: string;
14	};
15	
16	function money(cents: number) {
17	  const v = cents / 100;
18	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
19	}
20	
21	function planFeatures(p: PlanCard): string[] {
22	  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
23	  return [
24	    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
25	    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
26	    `${p.diskGB} GB ${disk}`,
27	    `${p.bandwidthTB} TB bandwidth`,
28	    "Full root access",
29	    "Free DDoS protection",
30	  ];
31	}
32	
33	export function PricingGrid({ plans }: { plans: PlanCard[] }) {
34	  // Highlight the middle plan (by position) as "Most popular".
35	  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;
36	
37	  if (plans.length === 0) {
38	    return (
39	      <div className="card text-center text-slate-400">
40	        Plans are being provisioned. Please check back shortly.
41	      </div>
42	    );
43	  }
44	
45	  // No promo banner here: first-month-free is a Shared Web Hosting offer only
46	  // (see lib/promo-redemption.ts firstMonthFreeAppliesTo). VPS bills the regular
47	  // price from month one — the price shown IS what checkout charges.
48	
49	  return (
50	    <div>
51	      <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
52	        {plans.map((p, i) => {
53	          const popular = i === popularIdx;
54	          const regular = p.priceCents;
55	          return (
56	          <div
57	            key={p.id}
58	            className={`group relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-300 hover:-translate-y-1.5 ${
59	              popular
60	                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
61	                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70 hover:shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.4)]"
62	            }`}
63	          >
64	            {popular && (
65	              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
66	                Most popular
67	              </span>
68	            )}
69	            <div className="flex items-center justify-between">
70	              <h3 className="text-base font-semibold text-white">{p.name}</h3>
71	              <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-300">
72	                {planAudience(p)}
73	              </span>
74	            </div>
75	            <div className="mt-3">
76	              <div className="flex items-end gap-1">
77	                <span className="text-4xl font-bold tracking-tight">{money(regular)}</span>
78	                <span className="mb-1 text-sm text-slate-400">/mo</span>
79	              </div>
80	              <p className="mt-1 text-[11px] leading-snug text-slate-500">
81	                Billed monthly. Cancel anytime.
82	              </p>
83	            </div>
84	            <div className="mt-4 flex items-start gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
85	              <span className="mt-0.5 text-brand-300" aria-hidden>
86	                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
87	                  <path d="M9 18h6M10 21h4M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1h6c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z" />
88	                </svg>
89	              </span>
90	              <p className="text-[12px] leading-snug text-slate-300">
91	                <span className="font-semibold text-slate-200">Great for: </span>
92	                {planTip(p)}
93	              </p>
94	            </div>
95	            <ul className="mt-5 flex-1 space-y-3 text-sm">
96	              {planFeatures(p).map((f) => (
97	                <li key={f} className="flex items-center gap-2.5 text-slate-300">
98	                  <span className="flex h-4.5 w-4.5 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
99	                    <IconCheck size={12} />
100	                  </span>
101	                  {f}
102	                </li>
103	              ))}
104	            </ul>
105	            <Link
106	              href="/register"
107	              className={`mt-7 w-full ${popular ? "btn-primary" : "btn-secondary"}`}
108	            >
109	              Deploy now
110	            </Link>
111	          </div>
112	          );
113	        })}
114	      </div>
115	    </div>
116	  );
117	}
