1	"use client";
2	
3	import { useEffect, useState } from "react";
4	
5	/**
6	 * Sticky product switcher for the /pricing multi-product hub. Pure navigation:
7	 * anchor links to the five DB-fed product sections (VPS · Game Servers · Shared
8	 * Hosting · Business Email · Domains) with an active-section highlight driven by
9	 * a scroll spy. It renders NO prices — every price on the page is server-rendered
10	 * from the database in the section it belongs to, so this component never risks
11	 * drifting from the catalogue.
12	 */
13	export type NavItem = { id: string; label: string; accent: "violet" | "emerald" | "cyan" | "sky" | "amber" };
14	
15	const ACCENT: Record<NavItem["accent"], { on: string; dot: string }> = {
16	  violet: { on: "from-accent-blue to-brand-500", dot: "bg-brand-400" },
17	  emerald: { on: "from-emerald-500 to-teal-500", dot: "bg-emerald-400" },
18	  cyan: { on: "from-accent-cyan to-accent-blue", dot: "bg-accent-cyan" },
19	  sky: { on: "from-sky-500 to-accent-blue", dot: "bg-sky-400" },
20	  amber: { on: "from-amber-500 to-orange-500", dot: "bg-amber-400" },
21	};
22	
23	export function PricingNav({ items }: { items: NavItem[] }) {
24	  const [active, setActive] = useState(items[0]?.id ?? "");
25	
26	  useEffect(() => {
27	    const sections = items
28	      .map((i) => document.getElementById(i.id))
29	      .filter((el): el is HTMLElement => !!el);
30	    if (sections.length === 0) return;
31	
32	    const observer = new IntersectionObserver(
33	      (entries) => {
34	        // Pick the entry nearest the top of the viewport that is intersecting.
35	        const visible = entries
36	          .filter((e) => e.isIntersecting)
37	          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
38	        if (visible[0]) setActive(visible[0].target.id);
39	      },
40	      // Bias the "active" band to just under the sticky header + nav.
41	      { rootMargin: "-150px 0px -55% 0px", threshold: 0 },
42	    );
43	    sections.forEach((s) => observer.observe(s));
44	    return () => observer.disconnect();
45	  }, [items]);
46	
47	  return (
48	    <div className="sticky top-[72px] z-40 -mx-5 border-b border-white/[0.06] bg-navy-950/85 px-5 backdrop-blur-xl">
49	      <nav className="rail flex gap-2 overflow-x-auto py-3 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
50	        {items.map((it) => {
51	          const on = active === it.id;
52	          const a = ACCENT[it.accent];
53	          return (
54	            <a
55	              key={it.id}
56	              href={`#${it.id}`}
57	              onClick={() => setActive(it.id)}
58	              className={`flex shrink-0 items-center gap-2 rounded-xl border px-4 py-2 text-sm font-semibold transition-all ${
59	                on
60	                  ? `border-transparent bg-gradient-to-r ${a.on} text-white shadow-lg`
61	                  : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/25 hover:text-white"
62	              }`}
63	            >
64	              <span className={`h-1.5 w-1.5 rounded-full ${on ? "bg-white" : a.dot}`} />
65	              {it.label}
66	            </a>
67	          );
68	        })}
69	      </nav>
70	    </div>
71	  );
72	}
