3	import { useMemo, useRef, useState } from "react";
4	import { useActionState, useEffect } from "react";
5	import { payAndDeploy, previewOrderCoupon } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { VersionPickerModal, type FamilyGroup } from "@/components/customer/VersionPickerModal";
8	// No vpsTermPriceCents here any more: every term price this wizard shows is now
9	// derived from lib/renewal-quote.ts (the regular/renewal rate) with the promo
10	// applied on top, so the file has exactly one source for what a term costs.
11	import { VPS_TERMS, vpsTerm, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
12	import { renewalQuote } from "@/lib/renewal-quote";
13	import { walletSplit } from "@/lib/wallet-split";
14	import {
15	  EXTRA_DISK_MAX_ADD_GB,
16	  EXTRA_DISK_MIN_GB,
17	  EXTRA_DISK_ONE_WAY_NOTE,
18	  EXTRA_DISK_STEP_GB,
19	  effectiveDiskGB,
20	  extraDiskCentsAt,
21	} from "@/lib/extra-disk";
22	
23	type Plan = {
24	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
25	  bandwidthTB: number; priceCents: number; storageTier: string;
26	};
27	type Image = {
28	  id: string; slug: string; name: string; category: string; family: string;
29	  version: string; logo: string; minRamMB: number; minDiskGB: number;
30	  licenseRequired: boolean; featured: boolean;
31	};
32	type NodeOpt = { id: string; name: string; publicIp: string };
33	
34	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
35	
36	/** sessionStorage key for the in-progress order — see the restore effect below. */
37	const DRAFT_KEY = "nxeon.deploy.draft.v1";
38	type Draft = {
39	  step: number;
40	  planId: string;
41	  nodeId: string;
42	  imageId: string;
43	  tab: string;
44	  addons: { malware: boolean; backup: boolean; docker: boolean };
45	  dedicatedIp: boolean;
46	  extraDiskGB: number;
47	  hostname: string;
48	  pubKey: string;
49	  termMonths: number;
50	  useWallet: boolean;
51	};
52	
53	/** APPLICATION-category images with one of these families are split into the Games tab. */
54	const GAME_FAMILIES = new Set(["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]);
55	
56	/** Install-step tabs. Games are peeled out of Applications into their own tab. */
57	const TABS = [
58	  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
59	  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
60	  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
61	  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
62	] as const;
63	
64	const OS_FAMILY_NAMES: Record<string, string> = {
65	  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
66	  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
67	};
68	/**
69	 * Human name for an image on the confirmation screen.
70	 *
71	 * Catalogue rows carry the version in BOTH `name` ("Ubuntu 20.04") and `version`
72	 * ("20.04"), so appending unconditionally printed "Ubuntu 20.04 20.04" — on the
73	 * last screen before the customer pays. Only append a version the name does not
74	 * already end with.
75	 */
76	function imageLabel(img: Image) {
77	  const version = img.version?.trim();
78	  if (!version) return img.name;
79	  return img.name.trim().endsWith(version) ? img.name : `${img.name} ${version}`;
80	}
81	
82	/** Clean family display name (no version) for the OS family cards. */
83	function osFamilyName(img: Image) {
84	  return OS_FAMILY_NAMES[img.family] ?? img.name.replace(/\s+\d.*$/, "").trim() ?? img.family;
85	}
86	
87	function Stepper({ step, steps }: { step: number; steps: string[] }) {
88	  return (
89	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
90	      {steps.map((s, i) => (
91	        <div key={s} className="flex items-center gap-2">
92	          <span
93	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
94	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
95	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
96	                  : "border-white/10 text-slate-500"
97	            }`}
98	          >
99	            {i < step ? "✓" : i + 1}
100	          </span>
101	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
102	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
103	        </div>
104	      ))}
105	    </div>
106	  );
107	}
108	
109	export function DeployWizard({
110	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
111	  extraDiskPriceCentsPerGb = 0,
112	  backupPlusPriceCents = 0,
113	  defaultPlanId, defaultTermMonths,
114	  promoPercent = 0, promoLabel,
115	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
116	}: {
117	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
118	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
119	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
120	  /**
121	   * Price per GB per month for extra ROOT DISK (admin setting
122	   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
123	   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
124	   * 0 hides the upsell entirely.
125	   */
126	  extraDiskPriceCentsPerGb?: number;
127	  /**
128	   * Monthly price of the Plus backup-retention tier (admin setting
129	   * `backup_plus_price_cents`). Priced over the term like the other add-ons so this
130	   * matches lib/order.ts orderQuote byte-for-byte.
131	   */
132	  backupPlusPriceCents?: number;
133	  /**
134	   * Plan pre-selected on step 1, from the `default_plan_slug` admin setting.
135	   *
136	   * An **id**, not the slug the setting stores: this component's `Plan` type carries no
137	   * slug, so matching here would mean widening the payload or matching on `name`. The
138	   * page resolves slug → id against the very array it passes down, so any id arriving
139	   * here is guaranteed to be in `plans`; a stale slug (plan renamed, or deactivated)
140	   * arrives as `undefined` and the wizard falls back to the first plan rather than
141	   * opening with nothing selected and no price on the Review step.
142	   */
143	  defaultPlanId?: string;
144	  /**
145	   * Billing term pre-selected on the Review step, in MONTHS, from `default_term`.
146	   *
147	   * Guaranteed by `defaultTermMonths()` to be one of `VPS_TERMS`. That guarantee is
148	   * load-bearing: the term buttons below are rendered straight from `VPS_TERMS` and
149	   * highlight on `termMonths === t.months`, so an unlisted value (the old setting's
150	   * "quarterly", say) would render a Review step with no term highlighted while the
151	   * hidden `termMonths` field still posted it — and `vpsTerm()` silently falls back to
152	   * monthly, so the customer would be charged for a term nothing on screen showed.
153	   */
154	  defaultTermMonths?: number;
155	  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
156	  promoPercent?: number; promoLabel?: string;
157	  /**
158	   * The admin ANNUAL discount (`annual_discount_percent`), resolved server-side and
159	   * passed in so the Annual term card's price, savings and `−X%` badge are the REAL
160	   * configured rate — the same one lib/order.ts charges and renewalCharge renews at.
161	   * Threaded into `renewalQuote` below so displayed === charged === renewed. Only
162	   * affects the 12-month card; every other term keeps its fixed rate.
163	   */
164	  annualDiscountPct?: number;
165	}) {
166	  const [state, action, pending] = useActionState(payAndDeploy, {} as { error?: string; checkoutUrl?: string });
167	  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
168	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
169	  const hasPromo = promoPercent > 0;
170	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
171	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
172	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
173	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
174	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
175	  const submittedRef = useRef(false);
176	  useEffect(() => {
177	    if (state?.checkoutUrl && submittedRef.current) {
178	      submittedRef.current = false;
179	      window.location.href = state.checkoutUrl;
180	    }
181	  }, [state]);
182	  const multiNode = nodes.length > 1;
183	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
184	  const [step, setStep] = useState(0);
185	
186	  const [planId, setPlanId] = useState(defaultPlanId ?? plans[0]?.id ?? "");
187	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
188	  const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
189	  const [tab, setTab] = useState<string>("os");
190	  const [modalFamily, setModalFamily] = useState<string | null>(null);
191	  const [q, setQ] = useState("");
192	  const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
193	  const [dedicatedIp, setDedicatedIp] = useState(false);
194	  // Backup RETENTION tier: "FREE" (keep 2, included) or "PLUS" (keep 7, paid).
195	  const [backupTier, setBackupTier] = useState<"FREE" | "PLUS">("FREE");
196	  // Extra ROOT DISK bought up front. One-way: this space can never be removed
197	  // later, which the Add-ons card and the Review step both state before payment.
198	  const [extraDiskGB, setExtraDiskGB] = useState(0);
199	  const [hostname, setHostname] = useState("");
200	  const [pubKey, setPubKey] = useState("");
201	  const [free, setFree] = useState(false);
202	  const [termMonths, setTermMonths] = useState(defaultTermMonths ?? VPS_TERMS[0].months);
203	  // Apply the wallet balance by default whenever there's something to apply.
204	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
205	  // Checkout promo code. `couponApplied` holds the server-verified discount so the
206	  // displayed total matches what placeOrder charges; it is cleared whenever the
207	  // selection changes (a "Starter only" code stops applying if they switch plans).
208	  const [couponInput, setCouponInput] = useState("");
209	  const [couponApplied, setCouponApplied] = useState<{ code: string; label: string; discountCents: number } | null>(null);
210	  const [couponMsg, setCouponMsg] = useState("");
211	  const [couponBusy, setCouponBusy] = useState(false);
212	  // Set when we come back from a cancelled Stripe Checkout, so the banner can
213	  // say what happened instead of leaving the customer on a silently reset form.
214	  const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);
215	
216	  /**
217	   * Keep the customer's choices alive across the Stripe round-trip.
218	   *
219	   * Cancelling on Stripe's page hard-navigates back to
220	   * `/dashboard/deploy?canceled=1`, which remounts this component from scratch:
221	   * plan, image, add-ons, disk slider, hostname and term all gone. `?canceled=1`
222	   * was read by nothing, so there was no explanation either — the customer just
223	   * found an empty wizard and had to guess whether they had been charged.
224	   *
225	   * sessionStorage is per-tab and survives that navigation where `useState`
226	   * cannot. The draft is written on every change and read back ONLY on a
227	   * `?canceled=1` return, then deleted — a draft that reappeared on some later
228	   * visit would be its own surprise.
229	   *
230	   * No root password is drafted or submitted: provisioning always generates one
231	   * server-side and shows it on the server page. There is no field to preserve.
232	   */
233	  useEffect(() => {
234	    let canceled = false;
235	    try {
236	      canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
237	    } catch {
238	      /* no URL access — fall through as a normal mount */
239	    }
240	    if (!canceled) return;
241	    let d: Draft | null = null;
242	    try {
243	      const raw = sessionStorage.getItem(DRAFT_KEY);
244	      sessionStorage.removeItem(DRAFT_KEY);
245	      if (raw) d = JSON.parse(raw) as Draft;
246	    } catch {
247	      d = null;
248	    }
249	    setRestoredAfterCancel(true);
250	    if (!d) return;
251	    // Every id is re-checked against the props actually rendered: a plan can be
252	    // deactivated or an image retired while the customer is on Stripe's page, and
253	    // selecting an id that is no longer in the list would show a blank Review
254	    // step with no price on it.
255	    if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
256	    if (nodes.some((n) => n.id === d.nodeId)) setNodeId(d.nodeId);
257	    if (images.some((i) => i.id === d.imageId)) setImageId(d.imageId);
258	    if (TABS.some((t) => t.key === d.tab)) setTab(d.tab);
259	    if (d.addons) setAddons({ malware: !!d.addons.malware, backup: !!d.addons.backup, docker: !!d.addons.docker });
260	    setDedicatedIp(!!d.dedicatedIp);
261	    if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(d.extraDiskGB);
262	    if (typeof d.hostname === "string") setHostname(d.hostname);
263	    if (typeof d.pubKey === "string") setPubKey(d.pubKey);
