7	export type Tier = {
8	  id: string;
9	  gameFamily: string;
10	  name: string;
11	  ramMB: number;
12	  cpuCores: number;
13	  diskGB: number;
14	  slots: number | null;
15	  priceCents: number;
16	  termMonths: number;
17	  featured: boolean;
18	};
19	export type GameMeta = { family: string; name: string; glyph: string };
