24	/**
25	 * Customer game-server deploy: pick a game, pick a tier, deploy. Charges the
26	 * tier's price from the wallet via orderGameServer (which redirects to the new
27	 * server on success).
28	 */
29	export function GameDeploy({
30	  games,
31	  tiers,
32	  balanceCents,
33	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
34	}: {
35	  games: GameMeta[];
36	  tiers: Tier[];
37	  balanceCents: number;
38	  /** Live admin annual discount (%), so the Annual card shows the REAL price/savings. */
39	  annualDiscountPct?: number;
40	}) {
41	  const firstGame = games[0]?.family ?? "";
42	  const [game, setGame] = useState(firstGame);
43	  const [selected, setSelected] = useState<string | null>(null);
44	  const [termMonths, setTermMonths] = useState(1);
45	  const [error, setError] = useState<string | null>(null);
46	  const [pending, start] = useTransition();
47	
48	  const gameTiers = useMemo(
49	    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
50	    [tiers, game],
51	  );
52	
53	  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
54	  // What this order costs at the chosen term — the SAME formula the server charges
55	  // (termPriceCents), so what's shown here is what's charged and renewed.
56	  const chargeCents = chosen ? termPriceCents(chosen.priceCents, termMonths, annualDiscountPct) : 0;
57	  const insufficient = chosen ? balanceCents < chargeCents : false;
58	
59	  function deploy() {
60	    if (!chosen) return;
61	    setError(null);
62	    start(async () => {
63	      const res = await orderGameServer(chosen.id, termMonths);
64	      // On success orderGameServer redirects; only errors return here.
65	      if (res?.error) setError(res.error);
66	    });
67	  }
68	
69	  return (
70	    <div className="space-y-6">
71	      {/* Step 1 — game */}
72	      <div>
73	        <p className="label mb-2">1 · Choose a game</p>
74	        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
75	          {games.map((g) => {
76	            const active = g.family === game;
77	            const count = tiers.filter((t) => t.gameFamily === g.family).length;
78	            return (
79	              <button
80	                key={g.family}
81	                onClick={() => {
82	                  setGame(g.family);
83	                  setSelected(null);
84	                  setError(null);
85	                }}
86	                className={`card card-hover flex flex-col items-center gap-1.5 py-4 text-center transition ${
87	                  active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
88	                }`}
89	              >
90	                <span className="text-2xl">{g.glyph}</span>
91	                <span className="text-sm font-medium text-white">{g.name}</span>
92	                <span className="text-[11px] text-slate-500">
93	                  {count} tier{count === 1 ? "" : "s"}
94	                </span>
95	              </button>
96	            );
97	          })}
98	        </div>
99	      </div>
100	
101	      {/* Step 2 — tier */}
102	      <div>
103	        <p className="label mb-2">2 · Choose a plan</p>
104	        {gameTiers.length === 0 ? (
105	          <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
106	        ) : (
107	          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
108	            {gameTiers.map((t) => {
109	              const active = t.id === selected;
110	              return (
111	                <button
112	                  key={t.id}
113	                  onClick={() => {
114	                    setSelected(t.id);
115	                    setError(null);
116	                  }}
117	                  className={`card card-hover text-left transition ${
118	                    active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
119	                  }`}
120	                >
121	                  <div className="flex items-center justify-between gap-2">
122	                    <span className="font-semibold text-white">{t.name}</span>
123	                    {t.featured && (
124	                      <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
125	                        Popular
126	                      </span>
127	                    )}
128	                  </div>
129	                  <p className="mt-2 text-2xl font-bold tracking-tight text-white">
130	                    {money(t.priceCents)}
131	                    <span className="text-sm font-normal text-slate-400">
132	                      {t.termMonths > 1 ? ` / ${t.termMonths} mo` : " / mo"}
133	                    </span>
134	                  </p>
135	                  <ul className="mt-3 space-y-1 text-sm text-slate-400">
136	                    <li>{gb(t.ramMB)} RAM · {t.cpuCores} vCPU</li>
137	                    <li>{t.diskGB} GB NVMe disk</li>
138	                    {t.slots != null && <li>Up to {t.slots} player slots</li>}
139	                  </ul>
140	                </button>
141	              );
142	            })}
143	          </div>
144	        )}
145	      </div>
146	
147	      {/* Step 3 — billing term */}
148	      {chosen && (
149	        <div>
150	          <p className="label mb-2">3 · Billing term</p>
151	          <div className="grid gap-3 sm:grid-cols-2">
152	            {PRODUCT_TERMS.map((t) => {
153	              const total = termPriceCents(chosen.priceCents, t.months, annualDiscountPct);
154	              const perMo = Math.round(total / t.months);
155	              const savings = chosen.priceCents * t.months - total;
156	              const disc = t.months === ANNUAL_TERM_MONTHS ? annualDiscountPct : t.discountPct;
157	              const on = termMonths === t.months;
158	              return (
159	                <button
160	                  key={t.months}
161	                  onClick={() => setTermMonths(t.months)}
162	                  className={`card relative text-left transition ${on ? "border-brand-400 ring-1 ring-brand-400/40" : "card-hover"}`}
163	                >
164	                  {disc > 0 && (
165	                    <span className="absolute right-3 top-3 rounded-full bg-emerald-500/20 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
166	                      −{disc}%
167	                    </span>
168	                  )}
169	                  <p className="text-sm font-semibold text-white">{t.label}</p>
170	                  <p className="mt-1 text-lg font-bold text-white">{money(perMo)}<span className="text-xs font-normal text-slate-400">/mo</span></p>
171	                  <p className="mt-0.5 text-[11px] text-slate-500">
172	                    {money(total)} billed {t.months === 1 ? "monthly" : `every ${t.short}`}
173	                  </p>
174	                  {savings > 0 && (
175	                    <p className="mt-1 text-[11px] font-medium text-emerald-300">
176	                      {money(total)}/yr · save {money(savings)} vs monthly
177	                    </p>
178	                  )}
179	                </button>
180	              );
181	            })}
182	          </div>
183	        </div>
184	      )}
185	
186	      {/* Step 4 — deploy */}
187	      {chosen && (
188	        <div className="card flex flex-wrap items-center justify-between gap-4">
189	          <div>
190	            <p className="text-sm text-slate-400">
191	              Deploying <span className="font-medium text-white">{chosen.name}</span>. You&apos;ll be charged{" "}
192	              <span className="font-medium text-white">{money(chargeCents)}</span> from your wallet
193	              (balance {money(balanceCents)}).
194	            </p>
195	            {error && <p className="mt-1 text-sm text-red-400">{error}</p>}
196	            {insufficient && !error && (
197	              <p className="mt-1 text-sm text-amber-400">Insufficient balance — top up your wallet first.</p>
198	            )}
199	          </div>
200	          <button className="btn-primary" disabled={pending || insufficient} onClick={deploy}>
201	            {pending ? "Deploying…" : "Deploy server"}
202	          </button>
203	        </div>
204	      )}
205	    </div>
206	  );
207	}
