565	/**
566	 * Per-domain SPF / DKIM / DMARC / MX self-check.
567	 *
568	 * WHY: "my mail goes to spam" was undiagnosable from inside the product. The
569	 * platform owner hit exactly this and had to diagnose it with an external
570	 * third-party tool, so every customer in the same position had no route at all.
571	 *
572	 * Two things this panel must never do, because both would make it the codebase's
573	 * recurring defect in a new place — a surface reporting an outcome it never
574	 * verified, here telling someone their mail is fine while it goes to spam:
575	 *
576	 *   1. Report a status the server did not derive from DNS. Every badge below
577	 *      comes from `checkEmailDeliverability`, which reads the zone's own
578	 *      AUTHORITATIVE nameservers (this host's `hosts: files myhostname dns`
579	 *      nsswitch order can answer a lookup out of /etc/hosts while looking like a
580	 *      real query — that produced one confidently wrong diagnosis already).
581	 *   2. Round a partial answer up. `unknown` renders as its own slate state, not
582	 *      as a pass, and the nameservers actually queried are printed so the result
583	 *      is auditable rather than taken on trust.
584	 *
585	 * Not auto-run: each check is several outbound DNS queries plus one Mailcow call,
586	 * and the customer has to be looking at it for the answer to be useful.
587	 */
588	function DeliverabilityPanel({
589	  subscriptionId,
590	  domainName,
591	}: {
592	  subscriptionId: string;
593	  domainName: string;
594	}) {
595	  const [report, setReport] = useState<DeliverabilityReport | null>(null);
596	  const [error, setError] = useState<string | null>(null);
597	  const [pending, start] = useTransition();
598	
599	  function run() {
600	    setError(null);
601	    start(async () => {
602	      const res = await checkEmailDeliverability(subscriptionId);
603	      if (res?.error) {
604	        setError(res.error);
605	        setReport(null);
606	      } else if (res?.report) {
607	        setReport(res.report);
608	      }
609	    });
610	  }
611	
612	  const failing = report?.checks.filter((c) => c.status === "fail").length ?? 0;
613	  const warning = report?.checks.filter((c) => c.status === "warn").length ?? 0;
614	  const unknown = report?.checks.filter((c) => c.status === "unknown").length ?? 0;
615	
616	  return (
617	    <div className="mt-3 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
618	      <div className="flex flex-wrap items-center justify-between gap-2">
619	        <div className="flex flex-wrap items-center gap-2">
620	          <span className="text-sm font-semibold text-white">Deliverability check</span>
