634	            ))}
635	        </div>
636	        <button className="btn-secondary py-1 text-xs" onClick={run} disabled={pending}>
637	          {pending ? "Checking DNS…" : report ? "Re-check" : "Check deliverability"}
638	        </button>
639	      </div>
640	
641	      <p className="mt-2 text-xs text-slate-400">
642	        Checks what <span className="font-mono">{domainName}</span> actually publishes for MX, SPF, DKIM
643	        and DMARC. If your mail is landing in spam, a failing row here is usually why.
644	      </p>
645	
646	      {error && (
647	        <div className="mt-2 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-400">
648	          {error}
649	        </div>
650	      )}
651	
652	      {report && (
653	        <div className="mt-3 space-y-2">
654	          {report.error && (
655	            <div className="rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2 text-xs text-amber-300">
656	              {report.error}
657	            </div>
658	          )}
659	
660	          {report.checks.map((c) => (
661	            <div key={c.key} className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3">
662	              <div className="flex flex-wrap items-center gap-2">
663	                <Badge tone={CHECK_TONE[c.status]}>{CHECK_LABEL[c.status]}</Badge>
