667	                </span>
668	              </div>
669	
670	              <div className="mt-2 grid gap-2 sm:grid-cols-2">
671	                <div className="min-w-0">
672	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Found</div>
673	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
674	                    {c.observed || "— nothing published —"}
675	                  </code>
676	                </div>
677	                <div className="min-w-0">
678	                  <div className="text-[11px] uppercase tracking-wide text-slate-500">Expected</div>
679	                  <code className="mt-0.5 block break-all rounded bg-white/[0.04] px-2 py-1 font-mono text-[11px] text-slate-200">
680	                    {c.expected || "—"}
