682	                </div>
683	              </div>
684	
685	              <p
686	                className={`mt-2 text-xs ${
687	                  c.status === "fail"
688	                    ? "text-red-400"
689	                    : c.status === "warn"
690	                      ? "text-amber-400"
691	                      : c.status === "pass"
692	                        ? "text-emerald-300/80"
693	                        : "text-slate-400"
