"use client";

import { PRODUCT_TERMS, ANNUAL_TERM_MONTHS, termPriceCents, type VpsTerm } from "@/lib/billing-terms";

/**
 * The persuasive billing-term ladder — ONE shared, DB-fed presentation of the
 * "commit longer, pay less" choice, used by every non-VPS product order flow
 * (Shared Hosting, Business Email, Game servers, NxCloud). The VPS deploy wizard
 * keeps its own richer ladder because it also layers a first-term promo and
 * per-term add-ons on top; everything here is the clean two-choice case.
 *
 * TRUTH BY CONSTRUCTION. Every number shown is derived from the caller's real
 * monthly base price (`monthlyCents`, a db.*Plan.priceCents) run through
 * `termPriceCents` with the SAME live `annualDiscountPct` the server charges and
 * renews at — see lib/order.ts / renewalCharge. Nothing here is a marketing
 * literal: the effective $/mo, the % off, the total billed and the amount saved
 * are all functions of the catalogue, so a plan edit or an admin discount change
 * propagates automatically and the ladder can never advertise a figure checkout
 * won't honour.
 *
 * PERSUASION: the longest term with a real discount is badged "Best value"; the
 * annual term (when it isn't itself the longest) is badged "Recommended". Callers
 * default their selection to the recommended (annual) term — monthly stays one
 * click away, clearly labelled "cancel anytime", so the nudge is honest.
 */

const money = (c: number) => `$${(c / 100).toFixed(2)}`;

export function TermLadder({
  monthlyCents,
  annualDiscountPct,
  value,
  onChange,
  terms = PRODUCT_TERMS,
  columns = "sm:grid-cols-2",
  size = "md",
}: {
  /** The plan's real monthly base price in cents (db.*Plan.priceCents). */
  monthlyCents: number;
  /** Live admin annual discount (%), passed through untouched to termPriceCents. */
  annualDiscountPct: number;
  /** Currently-selected term in months. */
  value: number;
  onChange: (months: number) => void;
  /** Which term set to render. Defaults to Monthly + Annual (the non-VPS products). */
  terms?: VpsTerm[];
  /** Tailwind grid-cols utility for the ladder row. */
  columns?: string;
  size?: "sm" | "md";
}) {
  const longestMonths = terms.reduce((m, t) => Math.max(m, t.months), 0);

  return (
    <div className={`grid gap-3 ${columns}`}>
      {terms.map((t) => {
        const total = termPriceCents(monthlyCents, t.months, annualDiscountPct);
        const perMo = Math.round(total / t.months);
        const monthlyRun = monthlyCents * t.months;
        const savings = monthlyRun - total;
        const disc = t.months === ANNUAL_TERM_MONTHS ? annualDiscountPct : t.discountPct;
        const on = value === t.months;
        const isMonthly = t.months === 1;
        const isLongest = t.months === longestMonths;
        const isAnnual = t.months === ANNUAL_TERM_MONTHS;
        // Best value = the longest term that actually discounts. Recommended =
        // annual, when a longer term outranks it (VPS-style 2/3-yr ladders).
        const ribbon = isLongest && disc > 0 ? "Best value" : isAnnual && disc > 0 ? "Recommended" : null;
        // Effective saving headline: annual reads "/yr", multi-year reads over the term.
        const savingLabel = isAnnual
          ? `Save ${money(savings)}/yr`
          : `Save ${money(savings)} over ${t.short}`;

        return (
          <button
            key={t.months}
            type="button"
            onClick={() => onChange(t.months)}
            aria-pressed={on}
            className={`group relative rounded-2xl border ${size === "sm" ? "p-3.5" : "p-4"} text-left transition ${
              on
                ? "border-brand-400 bg-brand-500/10 ring-1 ring-brand-400/40"
                : ribbon
                  ? "border-emerald-500/25 bg-emerald-500/[0.04] hover:border-emerald-400/50"
                  : "border-white/10 bg-white/[0.02] hover:border-white/25"
            }`}
          >
            {ribbon && (
              <span
                className={`absolute -top-2.5 left-4 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wider text-white shadow ${
                  ribbon === "Best value" ? "bg-gradient-to-r from-emerald-500 to-teal-500" : "bg-gradient-to-r from-accent-blue to-brand-500"
                }`}
              >
                {ribbon}
              </span>
            )}
            <div className="flex items-center justify-between gap-2">
              <span className="text-sm font-semibold text-white">{t.label}</span>
              {disc > 0 && (
                <span className="rounded-full bg-emerald-500/15 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
                  −{disc}%
                </span>
              )}
            </div>
            <p className="mt-1.5 flex items-baseline gap-1.5">
              <span className={`${size === "sm" ? "text-lg" : "text-2xl"} font-bold text-white tabular-nums`}>{money(perMo)}</span>
              <span className="text-xs text-slate-400">/mo</span>
              {disc > 0 && <span className="text-xs text-slate-500 line-through tabular-nums">{money(monthlyCents)}</span>}
            </p>
            <p className="mt-1 text-[11px] text-slate-500">
              {money(total)} billed {isMonthly ? "monthly" : `every ${t.short}`}
            </p>
            {savings > 0 ? (
              <p className="mt-1 text-[11px] font-semibold text-emerald-300">{savingLabel}</p>
            ) : (
              <p className="mt-1 text-[11px] text-slate-500">Flexible — cancel anytime</p>
            )}
          </button>
        );
      })}
    </div>
  );
}

